// WithTimeout is WithDeadline(parent, now+d) under the hood.
ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
defer cancel()

select {
case <-time.After(200 * time.Millisecond): // slow work
	fmt.Println("finished work")
case <-ctx.Done():
	fmt.Println("gave up:", ctx.Err())
}
// Output: gave up: context deadline exceeded

func worker(ctx context.Context, jobs <-chan int) error {
	for {
		select {
		case <-ctx.Done():
			return ctx.Err() // context.Canceled or DeadlineExceeded
		case j, ok := <-jobs:
			if !ok {
				return nil
			}
			process(j)
		}
	}
}

// ctx is ALWAYS the first parameter; never a struct field.
func GetUser(ctx context.Context, id string) (*User, error) {
	row := db.QueryRowContext(ctx, "SELECT name FROM users WHERE id=$1", id)
	var name string
	if err := row.Scan(&name); err != nil {
		return nil, err
	}
	return &User{ID: id, Name: name}, nil
}

