func handler(w http.ResponseWriter, r *http.Request) {
	// One budget for the whole request, derived from r.Context().
	ctx, cancel := context.WithTimeout(r.Context(), 300*time.Millisecond)
	defer cancel()

	// Threaded INTO the DB boundary...
	rows, err := db.QueryContext(ctx, "SELECT id FROM orders")
	if err != nil {
		http.Error(w, err.Error(), http.StatusGatewayTimeout)
		return
	}
	defer rows.Close()

	// ...and OUT across the gRPC boundary (deadline rides in metadata).
	resp, err := billing.Charge(ctx, &billpb.ChargeRequest{})
	_ = resp
	_ = err
}

func fetch(parent context.Context) (*Result, error) {
	ctx, cancel := context.WithTimeout(parent, 2*time.Second)
	defer cancel() // runs on EVERY return path — even success

	res, err := slowCall(ctx)
	if err != nil {
		return nil, err // defer still fires: timer released
	}
	return res, nil // defer fires here too: no leaked timer
}

