package main

import (
	"context"
	"database/sql"
	"net/http"
	"time"
)

func handler(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Give this request a 2s budget, derived from the request's context
		// (which is itself cancelled if the client disconnects).
		ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
		defer cancel() // release the timer no matter how we return

		// The deadline propagates INTO the query: if it fires, the driver
		// cancels the query and returns the connection to the pool.
		row := db.QueryRowContext(ctx, "SELECT name FROM users WHERE id = $1", r.PathValue("id"))
		var name string
		if err := row.Scan(&name); err != nil {
			if ctx.Err() == context.DeadlineExceeded {
				http.Error(w, "timeout", http.StatusGatewayTimeout)
				return
			}
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.Write([]byte(name))
	}
}

